export type EditPlan =
  | { kind: "parameters"; edits: ParamEdit[]; summary: string[] }
  | { kind: "model"; reason: string; candidates?: string[] };

const norm = (s: string) => s.toLowerCase().replace(/[_-]/g, " ").replace(/\s+/g, " ").trim();

/**
 * Recognise a change request that ONLY tweaks parameters. Grammar per clause (clauses split by "and", ",", ";"):
 *   [set|change|make|increase|decrease|lower|raise|reduce] [the] [<item or ability name>] <role word> (to|=) <value> [s|sec|seconds|ticks|blocks|%]
 * Seconds are the default unit for cooldowns and durations (x20 ticks). Every clause must parse and resolve to exactly
 * one parameter (narrowed by the item/ability names in the clause), else the request goes to the model.
 */
export function planDesignEdit(text: string, designs: ItemDesign[]): EditPlan {
  const params = designParams(designs);
  if (!text || text.length > 400) return { kind: "model", reason: "empty or long request" };
  if (/\b(add|new|remove|delete|instead|also|another|when|if|make it (shoot|fire|summon)|texture|model|recipe|craft|rename)\b/i.test(text)) return { kind: "model", reason: "structural change" };
  const clauses = text.split(/\s*(?:\band\b|,|;)\s*/i).map((c) => c.trim()).filter(Boolean);
  if (!clauses.length || clauses.length > 6) return { kind: "model", reason: "no clauses" };
  const edits: ParamEdit[] = [];
  const summary: string[] = [];
  const names = designs.flatMap((d) => [{ item: d.id, ability: undefined as string | undefined, words: [norm(d.id), norm(d.name.text)] }, ...d.abilities.map((a) => ({ item: d.id, ability: a.id, words: [norm(a.id), norm(a.name)] }))]);
  let lastScope: typeof names = [];
  for (const raw of clauses) {
    const c = norm(raw).replace(/[.!?]+$/, "");
    const m = /^(?:(?:please )?(?:set|change|make|increase|decrease|lower|raise|reduce|put|adjust)\s+)?(?:the\s+)?(.+)\s+(?:to|=)\s+(.+)$/.exec(c);
    if (!m) return { kind: "model", reason: `could not read "${raw}"` };
    let subject = m[1].replace(/'s\b/g, "").trim();
    // the value comes from the RAW clause (sound keys and texts keep their case and underscores)
    const rawValue = (/^.*\s(?:to|=)\s+(.+?)[.!?]*$/i.exec(raw.trim())?.[1] ?? m[2]).trim();
    const valueText = m[2].trim();
    // scope words: item / ability names in the subject (longest first); a clause without one inherits the previous clause's
    let scope = names.filter((n) => n.words.some((w) => w && subject.includes(w)));
    for (const w of scope.flatMap((x) => x.words).filter(Boolean).sort((a, b) => b.length - a.length)) subject = subject.replace(w, " ");
    if (!scope.length) scope = lastScope; else lastScope = scope;
    subject = subject.replace(/\b(the|of|on|for|its|my)\b/g, " ").replace(/\s+/g, " ").trim();
    const role = ROLE_WORDS.find(([re]) => re.test(subject))?.[1];
    if (!role) return { kind: "model", reason: `"${raw}" is not a known parameter (${subject || "nothing"})` };
    let cands = params.filter((p) => role.includes(p.role) || (role.includes("charges") && p.path.endsWith(".charges.max")));
    const abScope = scope.filter((s) => s.ability);
    const itScope = scope.filter((s) => !s.ability);
    if (abScope.length) cands = cands.filter((p) => abScope.some((s) => s.item === p.item && s.ability === p.ability));
    else if (itScope.length) cands = cands.filter((p) => itScope.some((s) => s.item === p.item));
    // an ability's own cooldown beats set_cooldown params; one strength per pull/push node
    if (role.includes("cooldown") && cands.some((p) => p.path.endsWith(".cooldown_ticks"))) cands = cands.filter((p) => p.path.endsWith(".cooldown_ticks"));
    if (cands.length !== 1) return { kind: "model", reason: cands.length ? `"${raw}" matches ${cands.length} settings` : `"${raw}" matches no setting`, candidates: cands.map((p) => p.path).slice(0, 8) };
    const p = cands[0];
    let value: number | string;
    if (p.kind === "sound" || p.kind === "text") {
      value = p.kind === "sound" ? rawValue.replace(/\s+/g, "").toLowerCase() : rawValue.replace(/^["']|["']$/g, "");
    } else {
      const n = /^(-?\d+(?:\.\d+)?)\s*(s|sec|secs|seconds?|ticks?|blocks?|%|percent|hearts?)?$/.exec(valueText);
      if (!n) return { kind: "model", reason: `"${valueText}" is not a number` };
      let x = Number(n[1]);
      const unit = n[2] ?? "";
      if (p.kind === "ticks") x = /^tick/.test(unit) ? x : x * 20; // seconds by default
      else if (/^(%|percent)$/.test(unit)) x = x / 100;
      else if (/^heart/.test(unit)) x = x * 2;
      value = p.kind === "num" ? x : Math.round(x);
    }
    edits.push({ path: p.path, value });
    summary.push(`${p.label}: ${p.value} -> ${value}`);
  }
  return { kind: "parameters", edits, summary };
}
