    const s = planDesignEdit("change the void pull sound to nx_r7design:void_reaper.boom", prev.designs);
    assert.ok(s.kind === "parameters" && s.edits[0].path === "items.void_reaper.abilities.void_pull.a2.sound" && s.edits[0].value === "nx_r7design:void_reaper.boom");
