    const amb = planDesignEdit("set the sound to minecraft:block.bell.use", prev.designs);
    assert.ok(amb.kind === "model" && (amb.candidates ?? []).length === 2, "two items play sounds: ambiguous");
    assert.equal(planDesignEdit("make it shoot fireballs instead", prev.designs).kind, "model");
    assert.equal(planDesignEdit("add a dash ability", prev.designs).kind, "model");
    assert.equal(planDesignEdit("set the cooldown to fast", prev.designs).kind, "model");
    const e = planDesignEdit("set the vigor cooldown to 99999 seconds", prev.designs);
    assert.ok(e.kind === "parameters");
    if (e.kind === "parameters") assert.equal(applyParameterEdits(prev.designs, e.edits).ok, false, "the cap still applies");
  });
