 21	 * Anything else (null, a typo, a future plan) is unknown -> null, and callers fail closed.
 22	 */
 23	export function normalizePlan(raw: unknown): AssetPlan | null {
 24	  if (typeof raw !== "string") return null;
 25	  const v = raw.trim().toLowerCase();
 26	  if (v === "all" || v === "yakko" || v === "all models") return "all";
