 49	/** Asset kinds the adapter's route rules recognise in the request text (deterministic keyword match, no AI). */
 50	export function detectAssetKinds(text: string, game = "minecraft"): BuildAssetKind[] {
 51	  const adapter = getAdapter(game);
 52	  if (!adapter || !text) return [];
 53	  const out = new Set<BuildAssetKind>();
 54	  for (const rule of adapter.routeRules) {
 55	    if (!rule.assetKinds?.length) continue;
 56	    if (!rule.keywords.some((k) => new RegExp(k, "i").test(text))) continue;
 57	    for (const k of rule.assetKinds) {
 58	      if (rule.buildAssetKinds?.length) { for (const b of rule.buildAssetKinds) if ((BUILD_ASSET_KINDS as readonly string[]).includes(b)) out.add(b as BuildAssetKind); break; }
 59	      if (k === "sound") out.add("sound");
 60	      else if (k === "texture" || k === "model") out.add("texture"); // item models are drawn with the texture pipeline
 61	    }
 62	  }
 63	  return BUILD_ASSET_KINDS.filter((k) => out.has(k));
 64	}
