 66	/** The request's own list: `assets: ["texture"]` or `assets: { texture: true }` (anything else is ignored). */
 67	export function explicitAssetKinds(raw: unknown): BuildAssetKind[] {
 68	  if (Array.isArray(raw)) return BUILD_ASSET_KINDS.filter((k) => raw.includes(k));
 69	  if (raw && typeof raw === "object") return BUILD_ASSET_KINDS.filter((k) => (raw as Record<string, unknown>)[k] === true);
 70	  return [];
 71	}
