 73	export function requestedAssetKinds(input: { explicit?: unknown; text?: string; existing?: BuildAssetKind[]; game?: string }): BuildAssetKind[] {
 74	  const s = new Set<BuildAssetKind>([...explicitAssetKinds(input.explicit), ...detectAssetKinds(input.text ?? "", input.game), ...(input.existing ?? [])]);
 75	  // a creature always comes with its sound set (the base mob is silenced), so it also asks for sounds
 76	  if (s.has("creature")) s.add("sound");
 77	  return BUILD_ASSET_KINDS.filter((k) => s.has(k));
 78	}
