 83	    if (!hasCapability(mcVersion, "animatedCreatures")) return `${CREATURE_DOWNGRADE} This mod targets ${mcVersion}.`;
 84	    if (!getVersion(mcVersion)?.buildable) return `Animated custom creatures need a Minecraft 26.x version Cyrus can build, and ${mcVersion} is not buildable yet, so Cyrus builds the plugin with ${FALLBACK.creature}.`;
 85	    return null;
 86	  }
 87	  const pf = resourcePackFormat(mcVersion, { needsItemModels: kind === "texture" });
 88	  if (kind === "texture" && !hasCapability(mcVersion, "itemModelDefinitions")) {
 89	    return `${WORD.texture} need Minecraft 1.21.4 or newer (item model definitions) and this mod targets ${mcVersion}, so Cyrus builds it with ${FALLBACK.texture}. Pick 1.21.4 or newer to get custom textures.`;
 90	  }
 91	  if (!pf.ok) return `${WORD[kind]} aren't available for Minecraft ${mcVersion} yet (${pf.error}), so Cyrus builds it with ${FALLBACK[kind]}.`;
