 95	/**
 96	 * Decide, per requested kind: plan gate first (create for a new mod, edit for a change), then the version, then
 97	 * whether the pipeline exists. `plan` is whatever the token economy says (`all`, `yakko`, `saka`, ...); unknown or
 98	 * missing -> nothing may be created (fail closed).
 99	 */
100	export function planBuildAssets(input: { plan: unknown; requested: BuildAssetKind[]; mcVersion: string; change?: boolean; existing?: BuildAssetKind[]; creaturesOn?: boolean }): BuildAssetPlan {
101	  const plan = normalizePlan(input.plan);
102	  const allowed: AllowedAssets = { texture: false, sound: false, creature: false };
103	  const decisions: BuildAssetDecision[] = [];
104	  const notices: string[] = [];
105	  for (const kind of BUILD_ASSET_KINDS.filter((k) => input.requested.includes(k))) {
106	    const g = canAsset(plan, GATE_KIND[kind], input.change ? "edit" : "create");
107	    if (!g.ok) {
108	      const code = g.code === "plan_unknown" ? "plan_unknown" : "asset_locked";
109	      // Keeping what the mod already has is never gated: say so instead of implying the textures disappear.
110	      const reason = input.existing?.includes(kind)
111	        ? `This mod's existing ${WORD[kind].toLowerCase()} are kept exactly as they are. ${g.reason}`
112	        : `${g.reason} Cyrus will build the plugin with ${FALLBACK[kind]} instead.`;
113	      decisions.push({ kind, code, reason, ...(g.needs ? { needs: g.needs } : {}) });
114	      notices.push(reason);
115	      continue;
116	    }
117	    const vr = versionReason(kind, input.mcVersion);
118	    if (vr) { decisions.push({ kind, code: "version", reason: vr }); notices.push(vr); continue; }
119	    if (!ASSET_PIPELINE_READY[kind] || (kind === "creature" && !(input.creaturesOn ?? creaturesEnabled()))) {
120	      const reason = kind === "creature" ? `Animated custom creatures are not switched on in Cyrus yet, so this mod uses ${FALLBACK.creature} for now.` : `${WORD[kind]} are not built into Cyrus yet, so this mod uses ${FALLBACK[kind]} for now.`;
121	      decisions.push({ kind, code: "not_ready", reason });
122	      notices.push(reason);
123	      continue;
124	    }
125	    allowed[kind] = true;
126	    decisions.push({ kind, code: "allowed" });
127	  }
128	  return { requested: [...input.requested].sort() as BuildAssetKind[], allowed, decisions, notices, plan };
129	}
130	
131	export const anyAllowed = (a: AllowedAssets) => BUILD_ASSET_KINDS.some((k) => a[k]);
132	export const planLabel = (p: AssetPlan | null) => (p ? PLAN_LABEL[p] : "unknown");

