    19	/**
    20	 * Decide the model and hold tokens for a build that is about to start. Call AFTER the
    21	 * request is validated and rate-limited, BEFORE the ModBuild row is created, with the id
    22	 * the row will get. Accounts outside the token economy (not live, not preview) pass
    23	 * through unchanged (`tracked: false`), keeping the pre-token behaviour.
    24	 */
    25	export async function gateBuild(i: { user: User; buildId: string; requested: CyrusModelId | undefined; baseModel: CyrusModelId | undefined; text: string; now?: Date }): Promise<BuildGate> {
    26	  const cfg = await loadTokenConfig();
    27	  // Defence in depth for the launch pair (lib/cyrus/launch-state.ts): a build that reaches here with the token economy
    28	  // not active for this account must not run unmetered. Private-preview accounts are always "active", so this only
    29	  // ever refuses a public account while cyrus_studio_public_enabled is on and cyrus_tok_live is off.
    30	  if (!(await tokensActiveFor(i.user, cfg))) return { ok: false, status: 403, code: "launch_pair", model: i.requested ?? i.baseModel, error: "Cyrus building isn't open yet." };
    31	  const now = i.now ?? new Date();
    32	  await ensureStarterTokens(i.user, cfg);
    33	  const tier = await tierOf(i.user.id, cfg, now);
    34	  let model: CyrusModelId = i.requested ?? i.baseModel ?? defaultModelFor(tier);
    35	  // A change to a version built on a locked model falls back to the best allowed one
    36	  // unless the customer explicitly asked for the locked model.
    37	  if (!i.requested && !canUseModel(tier, model)) model = defaultModelFor(tier);
    38	  if (cfg.enforce && !canUseModel(tier, model)) {
    39	    const need = tierForModel(model);
    40	    return { ok: false, status: 403, code: "model_locked", model, tier, error: `${cyrusModel(model).name} unlocks with the ${TIER_LABEL[need]} plan. Get tokens to unlock it, or pick ${tier === "free" || tier === "katara" ? "Katara" :
    41	  }
    42	  const range = reserveRange(model, complexityOf(i.text), cfg);
    43	  const r = await reserveTokens({
    44	    userId: i.user.id, buildId: i.buildId, model, need: range[0], now,
    45	    pick: (available) => reserveAmount(available, range),
    46	    dailyCap: () => dailyCapFor(i.user.createdAt, now, cfg),
    47	    allowShort: !cfg.enforce,
    48	  });
    49	  if (!r.ok) {
    50	    if (r.code === "daily_cap") return { ok: false, status: 429, code: "daily_cap", error: `You've used today's Cyrus limit (${fmt(r.cap ?? 0)} tokens a day). It frees up over the next 24 hours.` };
    51	    return { ok: false, status: 402, code: "insufficient_tokens", need: range[0], available: r.available, model, error: `This build needs about ${fmt(range[0])} tokens and you have ${fmt(r.available)}. Get tokens to keep building.` }
    52	  }
    53	  return { ok: true, model, reserved: r.amount, tracked: true };
    54	}
