    61	/**
    62	 * Settle a FINISHED build against its hold. Idempotent (no-op for unheld or non-terminal
    63	 * builds), so the routes, the page loader and the worker can all call it.
    64	 */
    65	export async function settleBuildTokens(row: Pick<ModBuild, "id" | "userId" | "status" | "errorCode" | "costUsd" | "cyrus">, now = new Date()): Promise<void> {
    66	  if (row.status !== "succeeded" && row.status !== "failed") return;
    67	  const res = await db.cyrusTokenReservation.findUnique({ where: { buildId: row.id } });
    68	  if (!res || res.status !== "held") return;
    69	  const cfg = await loadTokenConfig();
    70	  const model: CyrusModelId = isCyrusModel(res.model) ? res.model : (readCyrusMeta(row.cyrus).model ?? "saka");
    71	  const freeFailuresUsed = await db.cyrusTokenLedger.count({ where: { userId: row.userId, note: "failed_free", createdAt: { gt: new Date(now.getTime() - cfg.freeFailuresDays * DAY) } } });
    72	  const d = settleCharge({ status: row.status, errorCode: row.errorCode, costUsd: row.costUsd || 0, model, freeFailuresUsed }, cfg);
    73	  await settleReservation({ buildId: row.id, charge: d.charge, reason: d.reason, costUsd: row.costUsd || 0, now });
    74	}
