    76	export async function safeSettle(row: Parameters<typeof settleBuildTokens>[0]): Promise<void> {
    77	  try { await settleBuildTokens(row); } catch (e) { console.error("[cyrus-tokens] settle failed", row.id, (e as Error).message); }
    78	}

