71	    ...(fe.features.itemModel ? [] : [`Custom item models need Minecraft 1.21.4 or newer; on ${i.mcVersion} the items keep their base look.`]),
72	    ...(gp.menus || i.existingGameplay ? ["Menus are built from a typed design: buttons, paginated shop lists, item / XP / Vault money prices, permissions and dialogues; prices and texts stay editable in config.yml. No play
73	    ...(gp.quests || i.existingGameplay ? ["Quests are built from a typed design: steps with kill / collect / craft / visit / break / talk / survive objectives, branches, chains, daily or weekly repeats and rewards; progres
74	    ...(motion.motion ? ["Animated props (doors, hatches, turrets, stands) are built from a typed motion design as display entities: operators place them with a command, players click them; they are not saved with the world
75	  ];
76	  return { route: true, matched, notices: [], limits, ...gameplay, ...motion };
77	}
