async function timed<T>(t: { steps: StepResult[]; host: DeliveryHost }, step: DeliveryStep, fn: () => Promise<T>, detail?: (v: T) => string): Promise<T> {
  const t0 = Date.now();
  try {
    t.host.fault?.(step);
    const v = await fn();
    t.steps.push({ step, status: "ok", ms: Date.now() - t0, detail: detail ? detail(v).slice(0, 400) : "" });
    return v;
  } catch (e) {
    t.steps.push({ step, status: "failed", ms: Date.now() - t0, detail: errMsg(e) });
    if (e instanceof Refusal || e instanceof StepFail) throw e;
    throw new StepFail(step, errMsg(e));
  }
}
