export type DeliveryPayload = { v: 1; op: "deliver" | "uninstall"; buildId?: string; projectId?: string; serverModId?: string; restartPolicy?: "now" | "next_restart" };
const ID = /^[A-Za-z0-9_-]{1,64}$/;

/** The discriminator: null for every ordinary GAME_MOD_SYNC payload. */
export function readDeliveryPayload(payload: unknown): DeliveryPayload | null {
  const p = (payload && typeof payload === "object" ? (payload as Record<string, unknown>).cyrusDelivery : null) as Record<string, unknown> | null;
  if (!p || typeof p !== "object" || p.v !== 1) return null;
  if (p.op !== "deliver" && p.op !== "uninstall") return null;
  const id = (k: string) => (typeof p[k] === "string" && ID.test(p[k] as string) ? (p[k] as string) : undefined);
  const out: DeliveryPayload = { v: 1, op: p.op, buildId: id("buildId"), projectId: id("projectId"), serverModId: id("serverModId"), restartPolicy: p.restartPolicy === "next_restart" ? "next_restart" : "now" };
  if (out.op === "deliver" && !out.buildId) return null;
  if (out.op === "uninstall" && !out.projectId) return null;
  return out;
}

