// Cyrus R5: the sound RENDER RELAY. The web process never connects to node-2: it sends render / preview jobs to a
// small loopback HTTP relay inside the WORKER, and the worker holds the ssh transport to the render host
// (./host.ts sshRenderHost). No audio is ever rendered on the primary; the relay only forwards JSON.
//   worker:  CYRUS_SOUND_RENDER=ssh + CYRUS_SOUND_RELAY_PORT=<port> + CYRUS_SOUND_RELAY_TOKEN=<secret>  -> startRenderRelay
//   web:     CYRUS_SOUND_RENDER=relay + CYRUS_SOUND_RELAY_URL=http://127.0.0.1:<port> + the same token   -> relayRenderHost
// Endpoints (bearer token, loopback only): POST /render, POST /preview, GET /health (probe of the render host).
// One job at a time (node-2 serialises renders with flock anyway). Body cap 4 MB in, 16 MB (job output cap) out.
import http from "node:http";
import { timingSafeEqual } from "node:crypto";
import { NODE2, shq, sshRemote, type Remote } from "../testflight/client";
import { MAX_JOB_OUTPUT_BYTES, type PreviewJob, type PreviewResult, type RenderJob, type RenderResult } from "./job";
import { SOUND_FFMPEG_DIR, SOUND_LIBRARY_DIR, SOUND_RENDER_ROOT, type RenderHost } from "./host";

export const MAX_RELAY_BODY = 4 * 1024 * 1024;
export const RELAY_TOKEN_MIN = 24;
export type RenderHealth = { ok: boolean; host: string; checks: { id: "reachable" | "ffmpeg" | "library" | "workdir"; ok: boolean; detail: string }[]; ms: number };

const tokenOk = (got: string | undefined, want: string) => {
  if (!got || !got.startsWith("Bearer ")) return false;
  const a = Buffer.from(got.slice(7)), b = Buffer.from(want);
  return a.length === b.length && timingSafeEqual(a, b);
};

