// The sound RENDER HOST transport (Cyrus R1 sound slice), portal side. SERVER ONLY.
// Audio is never rendered on the primary: the portal sends a RenderJob (specs + library refs, no audio) to the render
// host and gets back the Ogg files and their measurements. The transport is injectable (like Test Flight's `Remote`):
//   sshRenderHost()  ships runner.bundle.cjs to node-2 once (content-addressed file name) and runs it there under
//                    flock + timeout + nice/ionice + a heap cap; one render at a time.
//   a fake RenderHost in the tests.
// OFF unless CYRUS_SOUND_RENDER=ssh: selectRenderHost() then says why, and the sync records the sounds as
// "unrendered" (the plugin still ships; no sound reaches players).
import { readFileSync } from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { NODE2, shq, sshRemote, type Remote } from "../testflight/client";
import { relayRenderHost } from "./relay";
import { MAX_JOB_OUTPUT_BYTES, type PreviewJob, type PreviewResult, type RenderJob, type RenderResult } from "./job";
import { cyrusConfig } from "../config";

export type RenderHost = {
  id: string;
  render: (job: RenderJob) => Promise<RenderResult>;
  /** Sound Studio audition of one library layer (short processed WAV); absent on hosts that cannot do it */
  preview?: (job: PreviewJob) => Promise<PreviewResult>;
};

export const SOUND_RENDER_ROOT = cyrusConfig().soundRenderRoot;
export const SOUND_LIBRARY_DIR = cyrusConfig().soundLibraryDir;
export const SOUND_FFMPEG_DIR = cyrusConfig().soundFfmpegDir;
export const RUNNER_BUNDLE = path.join(process.cwd(), "lib/cyrus/sound/runner.bundle.cjs");

export type SshHostOptions = { remote?: Remote; host?: string; root?: string; libraryDir?: string; ffmpegDir?: string; bundle?: Buffer; timeoutS?: number };

const SAFE_PATH = /^\/[A-Za-z0-9._/-]{1,200}$/;

export function sshRenderHost(o: SshHostOptions = {}): RenderHost {
  const remote = o.remote ?? sshRemote(o.host ?? NODE2);
  const root = o.root ?? SOUND_RENDER_ROOT, lib = o.libraryDir ?? SOUND_LIBRARY_DIR, ff = o.ffmpegDir ?? SOUND_FFMPEG_DIR;
  for (const p of [root, lib, ff]) if (!SAFE_PATH.test(p) || p.includes("..")) throw new Error(`unsafe render host path ${p}`);
  const timeoutS = Math.min(300, Math.max(10, o.timeoutS ?? 120));
  let bundle: Buffer | null = o.bundle ?? null;
  const exec = async (job: RenderJob | PreviewJob, limitS: number): Promise<RenderResult | PreviewResult> => {
    bundle ??= readFileSync(RUNNER_BUNDLE);
    const name = `runner-${createHash("sha256").update(bundle).digest("hex").slice(0, 16)}.cjs`;
    const target = `${root}/${name}`;
    // 1. the runner, once per content (atomic rename; never overwrites a different file under the same name)
    const put = await remote.exec(`set -e; mkdir -p ${shq(root)}; test -f ${shq(target)} || { cat > ${shq(target + ".part")} && mv ${shq(target + ".part")} ${shq(target)}; }`, { input: bundle, timeout
    if (put.code !== 0) return { ok: false, code: "transport", error: `could not place the runner: ${put.stderr.slice(-200)}` };
    // 2. the job: one render at a time on the host (flock), hard timeout, low priority, capped heap
    const cmd = `cd ${shq(root)} && exec flock -E 75 -w 90 ${shq(root + "/render.lock")} timeout -k 5 ${limitS} nice -n 10 ionice -c2 -n7 node --max-old-space-size=768 ${shq(name)} --ffmpeg ${shq(ff)}
    const r = await remote.exec(cmd, { input: Buffer.from(JSON.stringify(job)), timeoutMs: (limitS + 100) * 1000 });
    if (r.code === 124 || r.code === 137) return { ok: false, code: "timeout", error: "the render host timed out" };
    if (r.code === 75) return { ok: false, code: "busy", error: "the render host is busy" };
    if (r.stdout.length > MAX_JOB_OUTPUT_BYTES * 1.4) return { ok: false, code: "transport", error: "render output too large" };
    try { return JSON.parse(r.stdout) as RenderResult; }
    catch { return { ok: false, code: "transport", error: `bad render output (exit ${r.code}): ${r.stderr.slice(-200)}` }; }
  };
  return {
    id: `ssh:${o.host ?? NODE2}`,
    async render(job) { return (await exec(job, timeoutS)) as RenderResult; },
    async preview(job) { return (await exec(job, 30)) as PreviewResult; },
  };
}

