export async function svcCreate(body: { id: string; prompt: string; mcVersion: string; pluginName?: string; baseBuildId?: string; changeRequest?: string; tier?: "katara" | "saka" | "yakko"; images?: SvcImage[]; assets?: { texture: boolean; sound: boolean; namespace: string; library?: boolean } }): Promise<ServiceBuild> {
  const r = await call("/builds", { method: "POST", body: JSON.stringify(body), timeoutMs: body.images?.length ? 45_000 : 15_000 });
  const j = await r.json().catch(() => ({}));
  if (r.status !== 202) throw new Error((j as { error?: string }).error || `service returned ${r.status}`);
  return j as ServiceBuild;
}

